    /**
     * Tests getting all SemanticModels.
     *
     * @return    Collection
     */
    public List<SemanticModel> testGetAll() throws Throwable {
    LOGGER.info( "SemanticModelTest:testGetAll() - Retrieving Collection of SemanticModels:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all SemanticModel : " );
    List<SemanticModel> collection  = null;

    try {
        // call the static get method on the SemanticModelService
        collection = service.getAllSemanticModel();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            SemanticModel currEntity  = null;
            Iterator<SemanticModel> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getSemanticModelId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

